<?php

namespace App\Http\Controllers;

use Illuminate\Http\Request;

class AppointmentController extends Controller
{
    public function index()
    {
        $user = auth()->user();

        if ($user->role === 'student') {
            $appointments = Appointment::where('student_id', $user->id)->with('staff')->latest()->get();
        } elseif ($user->role === 'counselor') {
            $appointments = Appointment::where('staff_id', $user->id)->with('student')->latest()->get();
        } else {
            $appointments = Appointment::with(['student', 'staff'])->latest()->get();
        }

        return view('appointments.index', compact('appointments'));
    }

    public function store(Request $request)
    {
        $request->validate([
            'staff_id' => 'required|exists:users,id',
            'scheduled_at' => 'required|date|after:now',
            'purpose' => 'required|string|max:255',
            'notes' => 'nullable|string',
        ]);

        Appointment::create([
            'student_id' => auth()->id(),
            'staff_id' => $request->staff_id,
            'scheduled_at' => $request->scheduled_at,
            'purpose' => $request->purpose,
            'notes' => $request->notes,
            'status' => 'pending',
        ]);

        return redirect()->route('appointments.index')->with('success', 'Appointment requested successfully.');
    }

    public function updateStatus(Request $request, Appointment $appointment)
    {
        $request->validate([
            'status' => 'required|in:pending,approved,completed,rejected',
        ]);

        $appointment->update([
            'status' => $request->status,
        ]);

        return back()->with('success', 'Appointment status updated successfully.');
    }
}
